package com.medical.ui;
import com.formdev.flatlaf.FlatLightLaf;import com.medical.ui.panels.*;import com.medical.ui.utils.*;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;
public class MainFrame extends JFrame{
 private final JLabel status=new JLabel("  Prêt");private final JLabel clock=new JLabel();
 public MainFrame(){super("Centre Médical");FlatLightLaf.setup();UiStyle.install();setDefaultCloseOperation(EXIT_ON_CLOSE);setMinimumSize(new Dimension(1150,720));setSize(1280,780);setLocationRelativeTo(null);ApiClient api=new ApiClient();JPanel root=new JPanel(new BorderLayout());root.setBorder(new EmptyBorder(18,20,14,20));root.add(header(),BorderLayout.NORTH);JTabbedPane tabs=new JTabbedPane();tabs.setBorder(new EmptyBorder(12,0,0,0));tabs.addTab("  Médecins  ",new MedecinPanel(api,status));tabs.addTab("  Patients  ",new PatientPanel(api,status));tabs.addTab("  Visites  ",new VisitePanel(api,status));root.add(tabs,BorderLayout.CENTER);JPanel bottom=new JPanel(new BorderLayout());bottom.setBorder(new EmptyBorder(10,2,0,2));status.setForeground(new Color(75,85,99));bottom.add(status,BorderLayout.WEST);bottom.add(clock,BorderLayout.EAST);root.add(bottom,BorderLayout.SOUTH);setContentPane(root);updateClock();new Timer(1000,e->updateClock()).start();}
 private JPanel header(){JPanel h=new JPanel(new BorderLayout(15,0));JLabel title=new JLabel("Centre Médical");title.setFont(title.getFont().deriveFont(Font.BOLD,30f));JLabel sub=new JLabel("Gestion des médecins, patients et visites");sub.setForeground(new Color(107,114,128));sub.setFont(sub.getFont().deriveFont(14f));JPanel texts=new JPanel();texts.setLayout(new BoxLayout(texts,BoxLayout.Y_AXIS));texts.add(title);texts.add(Box.createVerticalStrut(4));texts.add(sub);JLabel badge=new JLabel("  ● API locale  ");badge.setOpaque(true);badge.setBackground(new Color(220,252,231));badge.setForeground(new Color(21,128,61));badge.setBorder(new EmptyBorder(8,8,8,8));h.add(texts,BorderLayout.WEST);h.add(badge,BorderLayout.EAST);return h;}
 private void updateClock(){clock.setText(java.time.LocalDateTime.now().format(java.time.format.DateTimeFormatter.ofPattern("dd/MM/yyyy  HH:mm:ss")));}
}
